// Whole packet generated by the official private Common Source3 producer.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {readCommonProgramFacts,verifyCommonProgramFacts} from '../../compiler/common-program-facts.mjs';
import {buildCommonProgramHir,printCommonProgramHir,readCommonProgramHir} from '../../compiler/common-program-hir.mjs';
import {commonProgramPhysical} from '../../compiler/common-program-physical.mjs';
import {createCommonProgramPublication} from '../../compiler/common-program-analysis.mjs';
import {commonProgramCore} from '../../compiler/common-program-core.mjs';
import {commonCoreSchema} from '../../compiler/common-program-plan.mjs';
import {commonEffects} from '../../compiler/common-program-effects.mjs';
import {commonMeter} from '../../compiler/common-program-common.mjs';
import {i32TypeId,sha256} from '../../compiler/identity.mjs';
const bytes=await fs.readFile(new URL('./common-program-constructor-default-source-v3.json',import.meta.url));
const facts=readCommonProgramFacts(bytes),context={family:'tsfg.common-program-context-candidate',version:3,factsBytes:bytes,expectedPackageId:facts.packageId};
const hir=buildCommonProgramHir(facts,context),physical=commonProgramPhysical(hir),contexts=[...physical.values.actual.contexts.values()];
const named=name=>hir.functions.find(fn=>fn.name===name),type=name=>hir.types.find(type=>type.name===name);
test('official Source3 retains original packet and reconstructs complete HIR3',()=>{
  assert.equal(hir.format.version,3);assert.equal(hir.snapshot.packageId,facts.packageId);assert.deepEqual(readCommonProgramHir(Buffer.from(printCommonProgramHir(hir))),hir);
  const numeric=hir.functions.find(fn=>fn.ownerType===type('Numeric').id&&fn.kind==='construction-body');
  assert.equal(numeric.parameterInitialization.steps.length,2);assert.equal(numeric.parameterInitialization.minimumArgumentCount,0);
  assert.ok(numeric.parameterInitialization.steps.every(step=>step.argumentType!==i32TypeId));
  assert.ok(numeric.parameters.every(parameter=>parameter.type===i32TypeId));
  assert.throws(()=>buildCommonProgramHir(facts,{...context,version:2}),/r03-common-program-context/);
});
test('official Source3 defaults emit Core through first publication and cold fixed consumption',()=>{
  assert.equal(sha256(bytes),'sha256:6d7d996c0fd2c8f857557e10093b5afb178b6f5a906b8e541ea5aba6e3d5c53f');
  // The permitted empty target request checks the complete writer path; it
  // grants no kernel execution or dynamic constructor proof.
  const publication=createCommonProgramPublication(hir),product=commonProgramCore(hir,publication,{targets:[]});
  assert.equal(product.hir.inputIdentity,facts.packageId);assert.deepEqual(product.proof.targets,[]);
  assert.equal(product.borrowProof,null);assert.ok(product.text.includes('schema = "'+commonCoreSchema+'"'));
  assert.ok(product.text.includes('tsfg_program.strict_equal'));
});
test('Source3 admission checks the owning parameter, expression anchors and raw argument capacity',()=>{
  for(const {mutate,code}of [
    {mutate:ctor=>{delete ctor.parameterInitialization;},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.steps.reverse();},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.steps.pop();},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.steps[0].argumentType='i32';},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.steps[0].binding=ctor.parameters[1].id;},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.steps[0].initializer.range.start++;},code:'r03-common-program-source'},
    {mutate:ctor=>{ctor.parameterInitialization.minimumArgumentCount=2;},code:'r03-common-program-parameter-initialization'},
    {mutate:ctor=>{ctor.parameterInitialization.hasParameterExpressions=false;},code:'r03-common-program-parameter-initialization'}
  ]){
    const changed=structuredClone(facts),ctor=changed.payload.types.find(type=>type.name==='Numeric').constructor;mutate(ctor);
    assert.equal(changed.packageId,facts.packageId);
    assert.throws(()=>verifyCommonProgramFacts(changed),error=>error instanceof TypeError&&'code'in error&&error.code===code&&error.code!=='r03-common-program-identity');
  }
});
test('a known Source3 Common-var DTO reports unsupported consumer capability',()=>{
  // Boundary-only negative: this is not an official Source var capture.
  const changed=structuredClone(facts),fn=changed.payload.functions.find(fn=>fn.name==='mark'),original=fn.body[0];
  fn.body[0]={kind:'varDeclaration',range:original.range,binding:fn.parameters[0].id,nameRange:fn.parameters[0].nameRange};
  assert.equal(changed.packageId,facts.packageId);
  assert.throws(()=>verifyCommonProgramFacts(changed),error=>error instanceof TypeError&&'code'in error&&error.code==='r03-common-program-capability');
});
test('a selected constructor signature is owned before its raw argument ordinals are read',()=>{
  const changed=structuredClone(facts),caller=changed.payload.functions.find(fn=>fn.name==='actualUndefined'),construction=caller.body.find(row=>row.kind==='constDeclaration').initializer;
  construction.signature.parameters.push('i32');construction.arguments.push(structuredClone(construction.arguments.at(-1)));
  assert.equal(changed.packageId,facts.packageId);
  assert.throws(()=>verifyCommonProgramFacts(changed),error=>error instanceof TypeError&&'code'in error&&error.code==='r03-common-program-construction');
});
test('omitted and actual undefined initialize parameters while explicit null is preserved',()=>{
  const absent=sha256('tsfg.type\0undefined'),nullId=sha256('tsfg.type\0null');
  for(const name of ['omitted','actualUndefined','inherited','derived','argumentsFirst','thisDefault']){
    const rows=contexts.filter(c=>c.root&&c.plan.owner.id===named(name).id);assert.ok(rows.length,name);
    for(const row of rows){assert.equal(row.normal,true,name);assert.equal(row.language,false,name);assert.deepEqual([...row.returned.tags],[i32TypeId],name);}
  }
  const rows=contexts.filter(c=>c.root&&c.plan.owner.id===named('nullActual').id);assert.ok(rows.length);
  for(const row of rows)assert.deepEqual([...row.returned.tags],[nullId]);
  const numeric=hir.functions.find(fn=>fn.ownerType===type('Numeric').id&&fn.kind==='construction-body'),plan=physical.plans.find(plan=>plan.owner.id===numeric.id);
  for(const parameter of numeric.parameters){
    const entry=plan.entry.parameters[plan.parameters.findIndex(p=>p.id===parameter.id)],raw=physical.values.capacity.observed.get(numeric.id+'/'+entry.name),stored=physical.values.capacity.observed.get('binding/'+parameter.id);
    assert.ok(raw.tags.has(absent));assert.equal(stored.tags.has(absent),false);assert.ok(stored.tags.has(i32TypeId));
  }
});
test('a default language throw retains earlier effects and is caught outside the constructor',()=>{
  const rows=contexts.filter(c=>c.root&&c.plan.owner.id===named('throwsAfterEffects').id);assert.ok(rows.length);
  for(const row of rows){assert.equal(row.normal,true);assert.equal(row.language,false);assert.deepEqual([...row.returned.tags],[i32TypeId]);}
  const broken=hir.functions.find(fn=>fn.ownerType===type('Broken').id&&fn.kind==='construction-body'),calls=contexts.filter(c=>c.plan.owner.id===broken.id&&!c.root);
  assert.ok(calls.length);assert.ok(calls.every(c=>c.language&&!c.normal));
  const total=hir.globals.find(global=>global.name==='total');
  for(const call of calls){const value=call.languageHeap.get('global:'+total.id);assert.ok(value);assert.deepEqual([...value.tags],[i32TypeId]);}
});
test('a default initializer that produces actual undefined keeps that actual value',()=>{
  const absent=sha256('tsfg.type\0undefined'),rows=contexts.filter(c=>c.root&&c.plan.owner.id===named('defaultStillUndefined').id);assert.ok(rows.length);
  for(const row of rows){assert.equal(row.normal,true);assert.deepEqual([...row.returned.tags],[absent]);}
});
test('official Source declaration order becomes single-evaluation constructor CFG order',()=>{
  const planFor=name=>physical.plans.find(plan=>plan.owner.id===(named(name)?.id??hir.functions.find(fn=>fn.ownerType===type(name).id&&fn.kind==='construction-body').id));
  const operations=plan=>plan.graph.blocks.flatMap(block=>block.instructions),mark=named('mark').id;
  const literal=(plan,register)=>{const op=plan.graph.registers.get(register).operation;return op?.name==='tsfg_program.constant'?op.properties.decimal:op&&['tsfg_program.value_copy','tsfg_program.view'].includes(op.name)?literal(plan,op.operands[0]):null;};
  const marks=plan=>new Map(operations(plan).filter(op=>op.name==='tsfg_program.invoke'&&op.properties.function_id===mark).map(op=>[literal(plan,op.operands[0]),op]));
  const reaches=(plan,from,to)=>{
    const blocks=plan.graph.blocks,source=blocks.find(block=>block.instructions.includes(from)),target=blocks.find(block=>block.instructions.includes(to));
    if(source===target)return source.instructions.indexOf(from)<source.instructions.indexOf(to);
    const pending=[...source.instructions.at(-1).successors],seen=new Set();
    while(pending.length){const id=pending.pop();if(seen.has(id))continue;seen.add(id);if(id===target.name)return true;pending.push(...blocks.find(block=>block.name===id).instructions.at(-1).successors);}return false;
  };
  const numeric=planFor('Numeric'),sequence=marks(numeric);assert.equal(sequence.size,4);
  for(const [a,b]of [['1','2'],['2','3'],['3','4']])assert.ok(reaches(numeric,sequence.get(a),sequence.get(b)),a+' before '+b);
  const caller=planFor('argumentsFirst'),arguments_=marks(caller),construct=operations(caller).find(op=>op.name==='tsfg_program.invoke'&&op.properties.function_id===numeric.owner.id);
  assert.equal(arguments_.size,2);assert.ok(reaches(caller,arguments_.get('8'),arguments_.get('9')));assert.ok(reaches(caller,arguments_.get('9'),construct));
  const derived=planFor('Derived'),dm=marks(derived),base=operations(derived).find(op=>op.name==='tsfg_program.invoke'&&op.properties.function_id===numeric.owner.id);
  assert.ok(reaches(derived,dm.get('6'),base));assert.ok(reaches(derived,base,dm.get('7')));assert.ok(reaches(derived,dm.get('7'),dm.get('8')));
  const broken=planFor('Broken'),bm=marks(broken),failure=operations(broken).find(op=>op.name==='tsfg_program.invoke'&&op.properties.function_id===named('fail').id);
  assert.ok(reaches(broken,bm.get('6'),failure));assert.ok(reaches(broken,failure,bm.get('5')));
  const later=broken.graph.blocks.find(block=>block.instructions.includes(bm.get('5'))),language=broken.graph.blocks.find(block=>block.name===failure.successors[1]);
  assert.ok(language.instructions.some(op=>op.name==='tsfg_program.return_throw'));assert.notEqual(language.name,later.name);
});
test('default expression calls, globals and language throws participate in complete Source effects',()=>{
  const effects=commonEffects(hir,commonMeter(2000000),physical),uppers=effects.derived(),numeric=hir.functions.find(fn=>fn.ownerType===type('Numeric').id&&fn.kind==='construction-body'),
    broken=hir.functions.find(fn=>fn.ownerType===type('Broken').id&&fn.kind==='construction-body'),total=hir.globals.find(global=>global.name==='total');
  assert.ok(uppers.get(numeric.id).globals.writes.includes(total.id));assert.equal(uppers.get(broken.id).facets.mayThrow,true);
  const details=effects.derive(numeric,uppers,true),defaults=numeric.parameterInitialization.steps.map(step=>step.initializer.range);
  for(const range of defaults)assert.ok(details.calls.some(call=>call.target===named('mark').id&&call.range.start>=range.start&&call.range.end<=range.end));
});
